// Prepare Upload (per-item, PASS branch only) — v2.1 (ZERO-SAFE + pose00 inference)
// - Preserves poseNumber: 0 even if upstream allowZeroPose flag is missing
// - Infers zero-mode from filenames/keys/QA snapshots (pose00 hints)
// - Prefers SW1-provided __meta.storageKey/uploadedFilename (single source of truth)
// - Fallback filename format matches live structure: poseNN[_rM].png (NO dash), /poses/ subfolder
// - Uses retry suffix _r1, _r2

const j0 = $json   || {};
const b0 = $binary || {};
const out = { json: { ...j0 }, binary: { ...b0 } };

/* helpers */
function firstDefined(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; } }
function asInt(v){ const n = Number(v); return Number.isFinite(n) ? Math.floor(n) : null; }
function pad2(n){ return String(n).padStart(2,'0'); }
function isNonEmptyStr(x){ return typeof x === 'string' && x.trim().length > 0; }
function hasPose00Str(s){ return typeof s === 'string' && /(?:^|\/|_)(pose[-_]?0{2})(?:\.|_|\/|$)/i.test(s); }

/* 0) strict pass gate */
const passed =
  j0.qaPass === true ||
  j0.qaCombinedPass === true ||
  (j0.qa && j0.qa.combined && j0.qa.combined.pass === true) ||
  j0.qaRetryPass === true;

if (!passed) {
  throw new Error('Prepare Upload: not on QA-pass path (qaPass/qaCombinedPass/qa.combined.pass).');
}

/* 1) choose the passing binary */
let gen = out.binary.generated || out.binary.final_generated || out.binary.generated_inline || null;
let sourceTag =
  (out.binary.generated ? 'generated'
    : out.binary.final_generated ? 'final_generated'
    : out.binary.generated_inline ? 'generated_inline'
    : null);

if (!gen) {
  const keys = Object.keys(out.binary || {});
  throw new Error(`Prepare Upload: missing image binary. Expected "generated". Present keys: [${keys.join(', ')}]`);
}

/* 2) identity */
const hash = firstDefined(
  out.json.characterHash,
  out.json.__meta?.characterHash,
  out.json.ctx?.characterHash
);
if (!isNonEmptyStr(hash) || hash.length < 4) {
  throw new Error('Prepare Upload: characterHash missing/invalid.');
}

/* 3) ZERO-SAFE pose resolution (same strategy as SW3 v3.2) */
const upstreamZero =
  out.json.__meta?.allowZeroPose === true ||
  out.json.allowZeroPose === true ||
  out.json.orderContext?.allowZeroPose === true ||
  false;

const zeroHint =
  hasPose00Str(out.json.generatedFileName) ||
  hasPose00Str(out.json.storageKey)        ||
  hasPose00Str(out.json.uploadKey)         ||
  hasPose00Str(out.json.__meta?.storageKey)||
  hasPose00Str(out.json.__meta?.uploadedFilename) ||
  out.json.pose?.poseNumber === 0 ||
  out.json.poseNumber === 0 ||
  out.json.currentPoseNumber === 0 ||
  out.json.index === 0 ||
  (out.json.__meta?.deriveQaPass?.snapshot?.expectedPoseNumber === 0) ||
  (out.json.__meta?.styleQaBuildRequest?.partsSummary?.poseNN_plain === 'pose00') ||
  (out.json.__meta?.styleQaBuildRequest?.partsSummary?.poseNN_hyphen === 'pose-00');

const allowZero = upstreamZero || zeroHint;

let poseRaw = firstDefined(
  out.json.poseNumber,
  out.json.currentPoseNumber,
  out.json.__meta?.poseNumber,
  out.json.pose?.poseNumber,
  // LAST resort: derive from item index respecting zero policy
  allowZero ? $itemIndex : ($itemIndex + 1)
);
let poseNum = asInt(poseRaw);
if (poseNum === null) poseNum = allowZero ? 0 : 1;
// If any zero hint present but we somehow got 1, correct down to 0
if (zeroHint && poseNum === 1) poseNum = 0;
// Upper guardrail only
if (poseNum > 99) poseNum = 99;

const NN = pad2(poseNum);

/* 4) retry info */
const retryAttempt = asInt(firstDefined(
  out.json.retryAttempt,
  out.json.qaRetry,
  out.json.__meta?.qaRetry
)) || 0;
const retrySuffix = retryAttempt > 0 ? `_r${retryAttempt}` : '';

/* 5) Use SW1-provided keys if available (single source of truth) */
let storageKey = out.json.__meta?.storageKey || out.json.uploadKey;
let filename   = out.json.__meta?.uploadedFilename || out.json.generatedFileName;

if (!storageKey || !filename) {
  // Fallback: compute using LIVE format (poseNN.png), NOT dashed
  const ASSETS_ROOT = firstDefined(out.json.assetsRoot, 'book-mvp-simple-adventure/order-generated-assets');
  filename  = `pose${NN}${retrySuffix}.png`;
  storageKey = `${ASSETS_ROOT}/characters/${hash}/poses/${filename}`.replace(/\/{2,}/g, '/');
  console.log('⚠ Computed storageKey (not provided by SW1):', storageKey);
} else {
  console.log('✓ Using SW1-provided storageKey:', storageKey);
}

/* 6) normalize binary */
const normalized = {
  ...gen,
  fileName: filename,
  mimeType: gen.mimeType || 'image/png',
  fileExtension: gen.fileExtension || 'png',
};
out.binary = { generated: normalized };

/* 7) annotate JSON */
const DEFAULT_R2 = 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev';
out.json.publicR2Url = out.json.publicR2Url || DEFAULT_R2;

out.json.poseNumber = poseNum;
out.json.currentPoseNumber = poseNum;
// optional: keep index coherent if downstream reads it
out.json.index = allowZero ? poseNum : (poseNum - 1);

// bytes detection
const bytes = Number(
  normalized.fileSize ??
  normalized.fileSizeInBytes ??
  normalized.size ??
  j0.generatedImage?.size ??
  j0.__meta?.bytes ??
  NaN
);
const bytesNum = Number.isFinite(bytes) ? bytes : null;

out.json.__meta = {
  ...(out.json.__meta || {}),
  allowZeroPose: allowZero,
  storageKey,
  uploadKey: storageKey,
  uploadedFilename: filename,
  characterHash: hash,
  poseNumber: poseNum,
  bytes: bytesNum,
  sw1Compatible: true,
  prepareUpload: {
    version: '2.1',
    filename,
    source: sourceTag || 'generated',
    usedSW1Keys: !!(out.json.__meta?.storageKey || out.json.uploadKey),
    zeroInference: {
      upstreamZero,
      zeroHint,
      hints: {
        generatedFileName: hasPose00Str(out.json.generatedFileName) || undefined,
        storageKey:        hasPose00Str(out.json.storageKey)        || undefined,
        uploadKey:         hasPose00Str(out.json.uploadKey)         || undefined,
        metaStorageKey:    hasPose00Str(out.json.__meta?.storageKey)|| undefined,
        metaUploaded:      hasPose00Str(out.json.__meta?.uploadedFilename) || undefined,
        poseFieldZero:     (out.json.pose?.poseNumber === 0) || undefined,
        directZero:        (out.json.poseNumber === 0 || out.json.currentPoseNumber === 0) || undefined,
        indexZero:         (out.json.index === 0) || undefined,
        qaExpectedZero:    (out.json.__meta?.deriveQaPass?.snapshot?.expectedPoseNumber === 0) || undefined,
        qaPlainZero:       (out.json.__meta?.styleQaBuildRequest?.partsSummary?.poseNN_plain === 'pose00') || undefined,
        qaHyphenZero:      (out.json.__meta?.styleQaBuildRequest?.partsSummary?.poseNN_hyphen === 'pose-00') || undefined
      }
    }
  }
};

// promote identifiers
out.json.characterHash = hash;
out.json.amazonOrderId = firstDefined(
  out.json.amazonOrderId,
  out.json.orderData?.amazonOrderId,
  'unknown-order'
);

console.log('✅ Prepare Upload v2.1 (ZERO-SAFE)', {
  itemIndex: $itemIndex,
  allowZeroPose: allowZero,
  poseNum,
  index: out.json.index,
  hash: hash.slice(0,8)+'…',
  filename,
  storageKey,
  bytes: bytesNum,
  source: sourceTag
});

return out;

// Memory Hygiene After Upload (SW3-05) — per-item
const j = $json || {};
const itemIdx = $itemIndex ?? 0;

// clear binaries by returning an empty binary object
const out = {
  json: j,
  binary: {}, // important: single object, not array
  pairedItem: $input?.item?.pairedItem ?? { item: itemIdx },
};

console.log(`🧹 Cleared binaries for ${j.characterHash || 'unknown'} pose ${j.poseNumber ?? j.currentPoseNumber ?? '?'} (item ${itemIdx})`);

if (global && typeof global.gc === 'function') {
  try { global.gc(); } catch {}
}

return out;

// SW3 - Return Upload Results (Complete Data) — v2.1 ZERO-SAFE
// - Preserves pose 0 (no 0→1 coercion)
// - Uses firstDefined() instead of || for numeric pose fields
// - Keeps storageKey/uploadKey symmetry and builds publicUrl safely

const input = $json || {};

// helpers
function firstDefined(...vals){
  for (const v of vals){
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
}
function joinUrl(base, path){
  if (!base || !path) return undefined;
  return `${String(base).replace(/\/+$/,'')}/${String(path).replace(/^\/+/,'')}`;
}

// zero-safe pose resolution
const poseNumber = firstDefined(
  input.poseNumber,
  input.currentPoseNumber,
  input.__meta?.poseNumber,
  input.pose?.poseNumber,
  input.index  // if upstream set index=0 for pose00
);

// keys/paths
const storageKey = firstDefined(input.storageKey, input.uploadKey);
const uploadKey  = firstDefined(input.uploadKey, storageKey);
const publicUrl  = firstDefined(
  input.publicUrl,
  joinUrl(input.publicR2Url, uploadKey)
);

// qa fields
const qaPass           = firstDefined(input.qaCombinedPass, input.qaPass, false) === true;
const qaCombinedPass   = qaPass;
const qaScore          = firstDefined(input.qa?.pose?.score, input.qaScore, null);
const styleScore       = firstDefined(input.qa?.style?.score?.style_cohesion, input.styleScore, null);
const qaReasons        = firstDefined(input.qa?.style?.reasons, input.qaReasons, []) || [];

// identity
const characterHash    = firstDefined(input.characterHash, input.ctx?.characterHash);
const amazonOrderId    = firstDefined(input.amazonOrderId, input.orderData?.amazonOrderId);

// build output
return {
  json: {
    // Success tracking
    success: true,
    uploadSuccess: true,

    // Identity (zero-safe pose)
    characterHash,
    poseNumber,                 // ← preserves 0
    currentPoseNumber: poseNumber,

    // Retry tracking
    retryAttempt: firstDefined(input.retryAttempt, input.retry?.attempt, 0) || 0,
    retryTag: firstDefined(input.retryTag, input.retry?.tag, null),

    // QA results
    qaPass,
    qaCombinedPass,
    qaScore,
    styleScore,
    qaReasons,
    qa: input.qa || null,

    // Upload paths
    uploadKey,
    storageKey,
    approvedKey: firstDefined(uploadKey, storageKey),
    generatedFileName: input.generatedFileName,

    // URLs
    publicUrl,

    // Metadata
    correlationId: input.correlationId,

    // For orchestrator
    assetsRoot: input.assetsRoot,
    publicR2Url: input.publicR2Url,
    characterPath: input.characterPath,
    amazonOrderId
  },
  binary: {}
};
